CREATE TRIGGER protect_funnel_configurations_published BEFORE UPDATE ON funnel_configurations FOR EACH ROW
BEGIN
IF OLD.status IN ('published','retired') AND (NOT (BINARY OLD.id<=>BINARY NEW.id) OR NOT (BINARY OLD.tenant_id<=>BINARY NEW.tenant_id) OR NOT (BINARY OLD.branch_id<=>BINARY NEW.branch_id) OR NOT (BINARY OLD.industry_channel_id<=>BINARY NEW.industry_channel_id) OR NOT (BINARY OLD.channel_version_id<=>BINARY NEW.channel_version_id) OR NOT (BINARY OLD.review_destination_id<=>BINARY NEW.review_destination_id) OR NOT (BINARY OLD.revision<=>BINARY NEW.revision) OR NOT (BINARY OLD.brand_title<=>BINARY NEW.brand_title) OR NOT (BINARY OLD.accent_hex<=>BINARY NEW.accent_hex) OR NOT (BINARY OLD.locale<=>BINARY NEW.locale) OR NOT (BINARY OLD.published_at<=>BINARY NEW.published_at) OR NOT (BINARY OLD.created_at<=>BINARY NEW.created_at) OR (OLD.status='published' AND NEW.status NOT IN ('published','retired')) OR (OLD.status='retired' AND NEW.status<>'retired')) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Published version is immutable'; END IF;
END
